import Fastify from "fastify";
import cors from "@fastify/cors";
import autoload from "@fastify/autoload";
import { PrismaClient } from "@prisma/client";
import dotenv from "dotenv";

dotenv.config();

const prisma = new PrismaClient();

declare module "fastify" {
  interface FastifyInstance {
    prisma: PrismaClient;
  }
}

const app = Fastify({
  logger: true,
});

app.register(cors);

app.decorate("prisma", prisma);

// JsonWebToken 유틸리티
import jwt from "jsonwebtoken";

const JWT_SECRET = process.env.JWT_SECRET || "ralph-secret";

// 인증 미들웨어
async function auth(req, reply) {
  const authHeader = req.headers.authorization;
  if (!authHeader) {
    return reply.code(401).send({ errors: { header: ["인증 토큰이 필요합니다"] } });
  }
  const parts = authHeader.split(" ");
  if (parts[0] !== "Token") {
    return reply.code(401).send({ errors: { header: ["올바른 형식으로 인증 토큰을 전달해주세요"] } });
  }
  try {
    const decoded = jwt.verify(parts[1], JWT_SECRET);
    req.userId = decoded.id;
  } catch {
    return reply.code(401).send({ errors: { header: ["유효하지 않은 토큰입니다"] } });
  }
}

// 유저 라우터
app.register(async function (fastify) {
  // 회원가입
  fastify.post("/api/users", async (req, reply) => {
    const body = req.body as any;
    const { username, email, password } = body.user;
    if (!username || !email || !password) {
      return reply.code(422).send({
        errors: {
          username: username ? [] : ["username은 필수입니다"],
          email: email ? [] : ["email은 필수입니다"],
          password: password ? [] : ["password는 필수입니다"],
        },
      });
    }
    // 중복 체크
    const existingUser = await fastify.prisma.user.findFirst({
      where: { OR: [{ username }, { email }] },
    });
    if (existingUser) {
      const err = [];
      if (existingUser.username === username) err.push("username이 이미 사용 중입니다");
      if (existingUser.email === email) err.push("email이 이미 사용 중입니다");
      return reply.code(422).send({ errors: { _message: err } });
    }
    const hashedPassword = await require("bcryptjs").hash(password, 10);
    const user = await fastify.prisma.user.create({
      data: { username, email, password: hashedPassword },
    });
    const token = jwt.sign({ id: user.id }, JWT_SECRET, { algorithm: "HS256" });
    return reply.code(201).send({
      user: {
        username: user.username,
        email: user.email,
        bio: user.bio,
        image: user.image,
        token,
      },
    });
  });

  // 로그인
  fastify.post("/api/users/login", async (req, reply) => {
    const { email, password } = (req.body as any).user;
    const user = await fastify.prisma.user.findUnique({ where: { email } });
    if (!user) {
      return reply.code(422).send({
        errors: { email: ["해당 이메일로 등록된 유저가 없습니다"] },
      });
    }
    const match = await require("bcryptjs").compare(password, user.password);
    if (!match) {
      return reply.code(422).send({
        errors: { password: ["비밀번호가 일치하지 않습니다"] },
      });
    }
    const token = jwt.sign({ id: user.id }, JWT_SECRET, { algorithm: "HS256" });
    return reply.code(200).send({
      user: {
        username: user.username,
        email: user.email,
        bio: user.bio,
        image: user.image,
        token,
      },
    });
  });

  // 현재 유저 정보 조회
  fastify.get("/api/user", { preHandler: auth }, async (req, reply) => {
    const user = await fastify.prisma.user.findUniqueOrThrow({
      where: { id: req.userId },
    });
    const token = req.headers.authorization!.split(" ")[1];
    return { user: { username: user.username, email: user.email, bio: user.bio, image: user.image, token } };
  });

  // 현재 유저 정보 수정
  fastify.put("/api/user", { preHandler: auth }, async (req, reply) => {
    const body = (req.body as any).user;
    const updates: any = {};
    if (body.username !== undefined) updates.username = body.username;
    if (body.email !== undefined) updates.email = body.email;
    if (body.bio !== undefined) updates.bio = body.bio === "" ? null : body.bio;
    if (body.image !== undefined) updates.image = body.image === "" ? null : body.image;
    if (body.password !== undefined) {
      updates.password = await require("bcryptjs").hash(body.password, 10);
    }
    if (updates.username || updates.email) {
      const conflicting = await fastify.prisma.user.findFirst({
        where: {
          id: { not: req.userId },
          OR: [
            updates.username !== undefined ? { username: updates.username } : undefined,
            updates.email !== undefined ? { email: updates.email } : undefined,
          ].filter(Boolean),
        },
      });
      if (conflicting) {
        const err: string[] = [];
        if (updates.username && conflicting.username === updates.username) err.push("username이 이미 사용 중입니다");
        if (updates.email && conflicting.email === updates.email) err.push("email이 이미 사용 중입니다");
        return reply.code(422).send({ errors: { _message: err } });
      }
    }
    const user = await fastify.prisma.user.update({
      where: { id: req.userId },
      data: updates,
    });
    const token = req.headers.authorization!.split(" ")[1];
    return {
      user: { username: user.username, email: user.email, bio: user.bio, image: user.image, token },
    };
  });
});

// 프로필 라우터
app.register(async function (fastify) {
  fastify.get("/api/profiles/:username", async (req, reply) => {
    const profile = await fastify.prisma.user.findUnique({
      where: { username: req.params.username },
      select: { id: true, username: true, bio: true, image: true, createdAt: true, updatedAt: true },
    });
    if (!profile) {
      return reply.code(404).send({ errors: { profile: ["프로필을 찾을 수 없습니다"] } });
    }
    return { profile };
  });

  fastify.post("/api/profiles/:username/follow", { preHandler: auth }, async (req, reply) => {
    const target = await fastify.prisma.user.findUnique({
      where: { username: req.params.username },
      select: { id: true },
    });
    if (!target) {
      return reply.code(404).send({ errors: { profile: ["프로필을 찾을 수 없습니다"] } });
    }
    if (target.id === req.userId) {
      return reply.code(422).send({ errors: { profile: ["자기 자신을 팔로우할 수 없습니다"] } });
    }
    await fastify.prisma.follow.create({
      data: { followerId: req.userId, followingId: target.id },
    });
    const profile = await fastify.prisma.user.findUnique({
      where: { username: req.params.username },
      select: { id: true, username: true, bio: true, image: true, createdAt: true, updatedAt: true },
    });
    const isFollowing = await fastify.prisma.follow.findUnique({
      where: { followerId_followingId: { followerId: req.userId, followingId: target.id } },
    });
    return { profile: { ...profile, following: !!isFollowing } };
  });

  fastify.delete("/api/profiles/:username/follow", { preHandler: auth }, async (req, reply) => {
    const target = await fastify.prisma.user.findUnique({
      where: { username: req.params.username },
      select: { id: true },
    });
    if (!target) {
      return reply.code(404).send({ errors: { profile: ["프로필을 찾을 수 없습니다"] } });
    }
    await fastify.prisma.follow.deleteMany({
      where: { followerId: req.userId, followingId: target.id },
    });
    const profile = await fastify.prisma.user.findUnique({
      where: { username: req.params.username },
      select: { id: true, username: true, bio: true, image: true, createdAt: true, updatedAt: true },
    });
    const isFollowing = await fastify.prisma.follow.findUnique({
      where: { followerId_followingId: { followerId: req.userId, followingId: target.id } },
    });
    return { profile: { ...profile, following: !!isFollowing } };
  });
});

// 아티클 라우터
app.register(async function (fastify) {
  // 아티클 생성
  fastify.post("/api/articles", { preHandler: auth }, async (req, reply) => {
    const body = (req.body as any).article;
    const { title, description, body: articleBody, tagList = [] } = body;
    if (!title || !description || !articleBody) {
      const errs: string[] = [];
      if (!title) errs.push("title은 필수입니다");
      if (!description) errs.push("description은 필수입니다");
      if (!articleBody) errs.push("body는 필수입니다");
      return reply.code(422).send({ errors: { article: errs } });
    }
    const slug = title.toLowerCase().replace(/\s+/g, "-");
    const author = await fastify.prisma.user.findUniqueOrThrow({ where: { id: req.userId } });
    const article = await fastify.prisma.article.create({
      data: {
        slug,
        title,
        description,
        body: articleBody,
        author: { connect: { id: req.userId } },
        tags: {
          create: tagList.map((t: string) => ({ tag: t.toLowerCase() })),
        },
      },
      include: { author: { select: { username: true, bio: true, image: true } }, tags: true },
    });
    const favorited = false;
    const favoritesCount = 0;
    return {
      article: { ...article, author, favorited, favoritesCount },
    };
  });

  // 아티클 목록 조회
  fastify.get("/api/articles", async (req, reply) => {
    const { author, tag, favorited, limit = "20", offset = "0" } = req.query as any;
    const lim = parseInt(limit, 10);
    const off = parseInt(offset, 10);

    const where: any = {};
    if (author) {
      const user = await fastify.prisma.user.findUnique({ where: { username: author }, select: { id: true } });
      if (!user) {
        return {
          articles: [],
          articlesCount: 0,
        };
      }
      where.authorId = user.id;
    }
    if (tag) {
      where.tags = { some: { tag: tag.toLowerCase() } };
    }
    if (favorited) {
      where.favorites = { some: { userId: req.headers.authorization ? undefined : undefined } };
    }

    let articles;
    let articlesCount;

    // favorited 쿼리는 별도 처리
    if (favorited) {
      const user = await fastify.prisma.user.findUnique({
        where: { username: favorited },
        select: { id: true },
      });
      if (!user) {
        articles = [];
        articlesCount = 0;
      } else {
        const favors = await fastify.prisma.favorite.findMany({
          where: { userId: user.id },
          select: { articleId: true },
        });
        const articleIds = favors.map((f) => f.articleId);
        if (articleIds.length === 0) {
          articles = [];
          articlesCount = 0;
        } else {
          articles = await fastify.prisma.article.findMany({
            where: { id: { in: articleIds }, ...where },
            take: lim,
            skip: off,
            orderBy: { createdAt: "desc" },
            include: {
              author: { select: { username: true, bio: true, image: true } },
              tags: true,
              favorites: true,
            },
          });
          articlesCount = articles.length;
          // Re-fetch all (since we filtered by IDs not matching the additional where)
          // Actually the additional where might conflict - let's do a proper query
          // Simplified: just get all favorited articles and filter
          const allFavored = await fastify.prisma.article.findMany({
            where: { id: { in: articleIds } },
            take: lim,
            skip: off,
            orderBy: { createdAt: "desc" },
            include: {
              author: { select: { username: true, bio: true, image: true } },
              tags: true,
            },
          });
          articles = allFavored;
          articlesCount = allFavored.length;
        }
      }
    } else {
      articles = await fastify.prisma.article.findMany({
        where,
        take: lim,
        skip: off,
        orderBy: { createdAt: "desc" },
        include: {
          author: { select: { username: true, bio: true, image: true } },
          tags: true,
        },
      });
      articlesCount = await fastify.prisma.article.count({ where });
    }

    const result = articles.map((a) => ({
      ...a,
      author: a.author,
      favorited: false,
      favoritesCount: a.favorites ? a.favorites.length : 0,
    }));

    return { articles: result, articlesCount };
  });

  // 아티클 상세 조회
  fastify.get("/api/articles/:slug", async (req, reply) => {
    const article = await fastify.prisma.article.findUnique({
      where: { slug: req.params.slug },
      include: { author: { select: { username: true, bio: true, image: true } }, tags: true, favorites: true },
    });
    if (!article) {
      return reply.code(404).send({ errors: { article: ["not found"] } });
    }
    return {
      article: {
        ...article,
        favorited: false,
        favoritesCount: article.favorites.length,
      },
    };
  });

  // 아티클 수정
  fastify.put("/api/articles/:slug", { preHandler: auth }, async (req, reply) => {
    const article = await fastify.prisma.article.findUnique({ where: { slug: req.params.slug } });
    if (!article) {
      return reply.code(404).send({ errors: { article: ["not found"] } });
    }
    if (article.authorId !== req.userId) {
      return reply.code(401).send({ errors: { article: ["이 아티클을 수정할 권한이 없습니다"] } });
    }
    const body = (req.body as any).article;
    const updates: any = {};
    if (body.title !== undefined) updates.title = body.title;
    if (body.description !== undefined) updates.description = body.description;
    if (body.body !== undefined) updates.body = body.body;
    if (body.tagList !== undefined) {
      if (body.tagList === null) {
        return reply.code(422).send({ errors: { article: ["tagList는 null일 수 없습니다"] } });
      }
      if (Array.isArray(body.tagList)) {
        // 기존 태그 삭제 후 새로 생성
        await fastify.prisma.articleTag.deleteMany({ where: { articleId: article.id } });
        if (body.tagList.length > 0) {
          await fastify.prisma.articleTag.createMany({
            data: body.tagList.map((t: string) => ({ articleId: article.id, tag: t.toLowerCase() })),
          });
        }
      }
    }
    // slug 변경 시 처리
    if (updates.title) {
      updates.slug = updates.title.toLowerCase().replace(/\s+/g, "-");
    }
    const updated = await fastify.prisma.article.update({
      where: { id: article.id },
      data: updates,
      include: { author: { select: { username: true, bio: true, image: true } }, tags: true, favorites: true },
    });
    return {
      article: {
        ...updated,
        favorited: false,
        favoritesCount: updated.favorites.length,
      },
    };
  });

  // 아티클 삭제
  fastify.delete("/api/articles/:slug", { preHandler: auth }, async (req, reply) => {
    const article = await fastify.prisma.article.findUnique({ where: { slug: req.params.slug } });
    if (!article) {
      return reply.code(404).send({ errors: { article: ["not found"] } });
    }
    if (article.authorId !== req.userId) {
      return reply.code(401).send({ errors: { article: ["이 아티클을 삭제할 권한이 없습니다"] } });
    }
    await fastify.prisma.article.delete({ where: { id: article.id } });
    return reply.code(204).send();
  });

  // 아티클 피드
  fastify.get("/api/articles/feed", { preHandler: auth }, async (req, reply) => {
    const { limit = "20", offset = "0" } = req.query as any;
    const lim = parseInt(limit, 10);
    const off = parseInt(offset, 10);

    // 팔로우한 유저들의 아티클 조회
    const follows = await fastify.prisma.follow.findMany({
      where: { followerId: req.userId },
      select: { followingId: true },
    });
    const followingIds = follows.map((f) => f.followingId);

    let articles: any[];
    let articlesCount: number;

    if (followingIds.length === 0) {
      articles = [];
      articlesCount = 0;
    } else {
      articles = await fastify.prisma.article.findMany({
        where: { authorId: { in: followingIds } },
        take: lim,
        skip: off,
        orderBy: { createdAt: "desc" },
        include: {
          author: { select: { username: true, bio: true, image: true } },
          tags: true,
          favorites: true,
        },
      });
      articlesCount = await fastify.prisma.article.count({
        where: { authorId: { in: followingIds } },
      });
    }

    const result = articles.map((a) => ({
      ...a,
      author: a.author,
      favorited: false,
      favoritesCount: a.favorites.length,
    }));

    return { articles: result, articlesCount };
  });

  // 코멘트 작성
  fastify.post("/api/articles/:slug/comments", { preHandler: auth }, async (req, reply) => {
    const article = await fastify.prisma.article.findUnique({ where: { slug: req.params.slug } });
    if (!article) {
      return reply.code(404).send({ errors: { article: ["not found"] } });
    }
    const { body } = (req.body as any).comment;
    if (!body) {
      return reply.code(422).send({ errors: { comment: ["body는 필수입니다"] } });
    }
    const comment = await fastify.prisma.comment.create({
      data: {
        body,
        articleId: article.id,
        authorId: req.userId,
      },
      include: { author: { select: { username: true, bio: true, image: true } } },
    });
    return { comment };
  });

  // 코멘트 목록 조회
  fastify.get("/api/articles/:slug/comments", async (req, reply) => {
    const article = await fastify.prisma.article.findUnique({ where: { slug: req.params.slug } });
    if (!article) {
      return reply.code(404).send({ errors: { article: ["not found"] } });
    }
    const comments = await fastify.prisma.comment.findMany({
      where: { articleId: article.id },
      orderBy: { createdAt: "desc" },
      include: { author: { select: { username: true, bio: true, image: true } } },
    });
    return { comments };
  });

  // 코멘트 삭제
  fastify.delete("/api/articles/:slug/comments/:id", { preHandler: auth }, async (req, reply) => {
    const comment = await fastify.prisma.comment.findUnique({
      where: { id: parseInt(req.params.id, 10) },
      select: { articleId: true, authorId: true },
    });
    if (!comment) {
      return reply.code(404).send({ errors: { comment: ["not found"] } });
    }
    const article = await fastify.prisma.article.findUnique({ where: { id: comment.articleId } });
    if (!article || article.slug !== req.params.slug) {
      return reply.code(404).send({ errors: { comment: ["not found"] } });
    }
    if (comment.authorId !== req.userId) {
      return reply.code(401).send({ errors: { comment: ["이 코멘트를 삭제할 권한이 없습니다"] } });
    }
    await fastify.prisma.comment.delete({ where: { id: comment.id } });
    return reply.code(204).send();
  });

  // 즐겨찾기 추가
  fastify.post("/api/articles/:slug/favorite", { preHandler: auth }, async (req, reply) => {
    const article = await fastify.prisma.article.findUnique({
      where: { slug: req.params.slug },
      include: { author: { select: { username: true, bio: true, image: true } }, tags: true, favorites: true },
    });
    if (!article) {
      return reply.code(404).send({ errors: { article: ["not found"] } });
    }
    await fastify.prisma.favorite.create({
      data: { userId: req.userId, articleId: article.id },
    });
    return {
      article: {
        ...article,
        favorited: true,
        favoritesCount: article.favorites.length + 1,
      },
    };
  });

  // 즐겨찾기 삭제
  fastify.delete("/api/articles/:slug/favorite", { preHandler: auth }, async (req, reply) => {
    const article = await fastify.prisma.article.findUnique({
      where: { slug: req.params.slug },
      include: { author: { select: { username: true, bio: true, image: true } }, tags: true, favorites: true },
    });
    if (!article) {
      return reply.code(404).send({ errors: { article: ["not found"] } });
    }
    await fastify.prisma.favorite.deleteMany({
      where: { userId: req.userId, articleId: article.id },
    });
    return {
      article: {
        ...article,
        favorited: false,
        favoritesCount: 0,
      },
    };
  });
});

// 태그 라우터
app.register(async function (fastify) {
  fastify.get("/api/tags", async (req, reply) => {
    const tags = await fastify.prisma.articleTag.findMany({
      select: { tag: true },
      distinct: ["tag"],
    });
    return { tags: tags.map((t) => ({ tag: t.tag })) };
  });
});

// 에러 핸들러
app.setErrorHandler((error, req, reply) => {
  if (error.statusCode === 404) {
    return reply.code(404).send({ errors: { message: ["not found"] } });
  }
  if (error.statusCode === 422) {
    return reply.code(422).send(error.message ? { errors: { _message: [error.message] } } : error);
  }
  if (error.statusCode === 401) {
    return reply.code(401).send(error.message ? { errors: { header: [error.message] } } : { errors: { header: ["인증이 필요합니다"] } });
  }
  req.log.error(error);
  return reply.code(500).send({ errors: { message: ["서버 내부 오류가 발생했습니다"] } });
});

const start = async () => {
  try {
    const port = process.env.PORT || "3000";
    await app.listen({ port, host: "0.0.0.0" });
    app.log.info(`서버가 http://0.0.0.0:${port} 에서 실행 중입니다`);
  } catch (err) {
    app.log.error(err);
    process.exit(1);
  }
};

start();

// Graceful shutdown
process.on("SIGINT", async () => {
  await prisma.$disconnect();
  process.exit(0);
});
process.on("SIGTERM", async () => {
  await prisma.$disconnect();
  process.exit(0);
});

