  fastify.put("/api/articles/:slug", { preHandler: authMiddleware }, async (req, reply) => {
    const slug = (req.params as any).slug as string;
    const article = await prisma.article.findUnique({ where: { slug } });
    if (!article) {
      return reply.code(404).send({ errors: { article: ["not found"] } });
    }
    if (article.authorId !== req.userId!) {
      return reply.code(401).send({ errors: { article: ["이 아티클을 수정할 권한이 없습니다"] } });
    }

    const body = (req.body as any)?.article || {};
    const updates: any = {};
    if (body.title !== undefined) updates.title = body.title;
    if (body.description !== undefined) updates.description = body.description;
    if (body.body !== undefined) updates.body = body.body;

    if (body.tagList !== undefined) {
      if (body.tagList === null) {
        return reply.code(422).send({ errors: { article: ["tagList는 null일 수 없습니다"] } });
      }
      if (Array.isArray(body.tagList)) {
        await prisma.articleTag.deleteMany({ where: { articleId: article.id } });
        if (body.tagList.length > 0) {
          await prisma.articleTag.createMany({
            data: body.tagList.map((t: string) => ({ articleId: article.id, tag: t.toLowerCase() })),
          });
        }
      }
    }

    if (updates.title) {
      updates.slug = updates.title.toLowerCase().replace(/\s+/g, "-");
    }

    const updated = await prisma.article.update({
      where: { id: article.id },
      data: updates,
      include: { author: { select: { username: true, bio: true, image: true } }, tags: true, favorites: true },
    });
    return { article: { ...updated, favorited: false, favoritesCount: updated.favorites.length } };
  });

  // 아티클 삭제
  fastify.delete("/api/articles/:slug", { preHandler: authMiddleware }, async (req, reply) => {
    const slug = (req.params as any).slug as string;
    const article = await prisma.article.findUnique({ where: { slug } });
    if (!article) {
      return reply.code(404).send({ errors: { article: ["not found"] } });
    }
    if (article.authorId !== req.userId!) {
      return reply.code(401).send({ errors: { article: ["이 아티클을 삭제할 권한이 없습니다"] } });
    }
    await prisma.article.delete({ where: { id: article.id } });
    return reply.code(204).send();
  });

  // 아티클 피드
  fastify.get("/api/articles/feed", { preHandler: authMiddleware }, async (req, reply) => {
    const { limit = "20", offset = "0" } = req.query as any;
    const lim = parseInt(limit, 10);
    const off = parseInt(offset, 10);

    const follows = await prisma.follow.findMany({
      where: { followerId: req.userId! },
      select: { followingId: true },
    });
    const followingIds = follows.map((f) => f.followingId);

    let articles: any[];
    let articlesCount: number;

    if (followingIds.length === 0) {
      articles = [];
      articlesCount = 0;
    } else {
      articles = await prisma.article.findMany({
        where: { authorId: { in: followingIds } },
        take: lim,
        skip: off,
        orderBy: { createdAt: "desc" },
        include: {
          author: { select: { username: true, bio: true, image: true } },
          tags: true,
          favorites: true,
        },
      });
      articlesCount = await prisma.article.count({
        where: { authorId: { in: followingIds } },
      });
    }

    return {
      articles: articles.map((a: any) => ({ ...a, favorited: false, favoritesCount: a.favorites.length })),
      articlesCount,
    };
