      if (!target) return reply.code(404).send({ errors: { profile: ["프로필을 찾을 수 없습니다"] } });
      if (target.id === req.userId!) return reply.code(422).send({ errors: { profile: ["자기 자신을 팔로우할 수 없습니다"] } });
      await prisma.follow.upsert({
        where: { followerId_followingId: { followerId: req.userId!, followingId: target.id } },
        create: { followerId: req.userId!, followingId: target.id },
        update: {},
      });
      const profile = await prisma.user.findUnique({ where: { username }, select: { id: true, username: true, bio: true, image: true } });
      const isFollowing = await prisma.follow.findUnique({
        where: { followerId_followingId: { followerId: req.userId!, followingId: target.id } },
      });
      return { profile: { ...profile, following: !!isFollowing } };
