import Fastify, { FastifyInstance, FastifyRequest, FastifyReply, FastifyPluginCallback } from "fastify";
import { PrismaClient } from "@prisma/client";
import jwt from "jsonwebtoken";
import bcrypt from "bcryptjs";
import dotenv from "dotenv";

dotenv.config();

// Prisma 클라이언트
const prisma = new PrismaClient();
const JWT_SECRET = process.env.JWT_SECRET || "ralph-secret";

// Fastify 타입 확장
declare module "fastify" {
  interface FastifyRequest {
    userId?: number;
  }
}

// 사용자 응답 포맷터
function formatUserResponse(user: { username: string; email: string; bio: string | null; image: string | null }, token: string) {
  return { user: { username: user.username, email: user.email, bio: user.bio, image: user.image, token } };
}

// 아티클 응답 포맷터
function formatArticleResponse(article: any, isFavorited: boolean, favoritesCount: number) {
  return { ...article, favorited: isFavorited, favoritesCount };
}

// 인증 미들웨어
async function authMiddleware(req: FastifyRequest, reply: FastifyReply) {
  const authHeader = req.headers.authorization as string | undefined;
  if (!authHeader) {
    return reply.code(401).send({ errors: { header: ["인증 토큰이 필요합니다"] } });
  }
  const parts = authHeader.split(" ");
  if (parts[0] !== "Token") {
    return reply.code(401).send({ errors: { header: ["올바른 형식으로 인증 토큰을 전달해주세요"] } });
  }
  try {
    const decoded = jwt.verify(parts[1], JWT_SECRET) as { id: number };
    req.userId = decoded.id;
    // 토큰 갱신: 헤더에서 가져온 원래 토큰을 그대로 사용
    // (JWT이므로 파싱 없이 그대로 반환)
  } catch {
    return reply.code(401).send({ errors: { header: ["유효하지 않은 토큰입니다"] } });
  }
}

//          _ _                           _ _
//         | (_)                         | (_)
// __ _ ___| |_ _ __ ___  _ __   ___  __| | |
/// _` / __| | | '_ ` _ \| '_ \ / _ \/ _` | |
//| (_| \__ \ | | | | | | | | | (_) (_| | |
// \__,_|___/_|_| |_| |_|_| |_|\___/\__,_|_|
//       API Server

// Fastify 앱 초기화
const app: FastifyInstance = Fastify({
  logger: true,
});

// CORS 설정
await app.register(import("@fastify/cors"), { origin: true });

// ──────────────────────────────────────────────────────────────
// 사용자 API
// ──────────────────────────────────────────────────────────────
await app.register(async function (fastify: FastifyInstance) {
  // 회원가입
  fastify.post("/api/users", async (req, reply) => {
    const { username, email, password } = (req.body as any)?.user || {};
    if (!username || !email || !password) {
      const errs: string[] = [];
      if (!username) errs.push("username은 필수입니다");
      if (!email) errs.push("email은 필수입니다");
      if (!password) errs.push("password는 필수입니다");
      return reply.code(422).send({ errors: { _message: errs } });
    }
    const existing = await prisma.user.findFirst({
      where: { OR: [{ username }, { email }] },
    });
    if (existing) {
      const err: string[] = [];
      if (existing.username === username) err.push("username이 이미 사용 중입니다");
      if (existing.email === email) err.push("email이 이미 사용 중입니다");
      return reply.code(422).send({ errors: { _message: err } });
    }
    const hashedPassword = await bcrypt.hash(password, 10);
    const user = await prisma.user.create({
      data: { username, email, password: hashedPassword },
    });
    const token = jwt.sign({ id: user.id }, JWT_SECRET, { algorithm: "HS256" });
    return reply.code(201).send(formatUserResponse(user, token));
  });

  // 로그인
  fastify.post("/api/users/login", async (req, reply) => {
    const { email, password } = (req.body as any)?.user || {};
    const user = await prisma.user.findUnique({ where: { email: email as string } });
    if (!user) {
      return reply.code(422).send({ errors: { email: ["해당 이메일로 등록된 유저가 없습니다"] } });
    }
    const match = await bcrypt.compare(password, user.password);
    if (!match) {
      return reply.code(422).send({ errors: { password: ["비밀번호가 일치하지 않습니다"] } });
    }
    const token = jwt.sign({ id: user.id }, JWT_SECRET, { algorithm: "HS256" });
    return reply.code(200).send(formatUserResponse(user, token));
  });

  // 현재 사용자 조회
  fastify.get("/api/user", { preHandler: authMiddleware }, async (req, reply) => {
    const user = await prisma.user.findUniqueOrThrow({ where: { id: req.userId! } });
    const token = (req.headers.authorization as string).split(" ")[1];
    return formatUserResponse(user, token);
  });

  // 사용자 정보 수정
  fastify.put("/api/user", { preHandler: authMiddleware }, async (req, reply) => {
    const body = (req.body as any)?.user || {};
    const updates: any = {};
    if (body.username !== undefined) updates.username = body.username;
    if (body.email !== undefined) updates.email = body.email;
    if (body.bio !== undefined) updates.bio = body.bio === "" ? null : body.bio;
    if (body.image !== undefined) updates.image = body.image === "" ? null : body.image;
    if (body.password !== undefined) updates.password = await bcrypt.hash(body.password, 10);

    // 고유성 검증 (username 또는 email 변경 시)
    if (updates.username || updates.email) {
      const existing = await prisma.user.findFirst({
        where: {
          id: { not: req.userId! },
          OR: [
            updates.username !== undefined ? { username: updates.username } : undefined,
            updates.email !== undefined ? { email: updates.email } : undefined,
          ].filter((e: any) => e !== undefined),
        },
      });
      if (existing) {
        const err: string[] = [];
        if (updates.username && existing.username === updates.username) err.push("username이 이미 사용 중입니다");
        if (updates.email && existing.email === updates.email) err.push("email이 이미 사용 중입니다");
        return reply.code(422).send({ errors: { _message: err } });
      }
    }

    const user = await prisma.user.update({
      where: { id: req.userId! },
      data: updates,
    });
    const token = (req.headers.authorization as string).split(" ")[1];
    return formatUserResponse(user, token);
  });
});

// ──────────────────────────────────────────────────────────────
// 프로필 API
// ──────────────────────────────────────────────────────────────
await app.register(async function (fastify: FastifyInstance) {
  // 프로필 조회
  fastify.get("/api/profiles/:username", async (req, reply) => {
    const username = (req.params as any).username as string;
    const profile = await prisma.user.findUnique({
      where: { username },
      select: { id: true, username: true, bio: true, image: true },
    });
    if (!profile) {
      return reply.code(404).send({ errors: { profile: ["프로필을 찾을 수 없습니다"] } });
    }

    // 인증 토큰에서 팔로우 상태 확인
    const authHeader = req.headers.authorization as string | undefined;
    let following = false;
    if (authHeader) {
      const parts = authHeader.split(" ");
      if (parts[0] === "Token") {
        try {
          const decoded = jwt.verify(parts[1], JWT_SECRET) as { id: number };
          const follow = await prisma.follow.findUnique({
            where: { followerId_followingId: { followerId: decoded.id, followingId: profile.id } },
          });
          following = !!follow;
        } catch {
          following = false;
        }
      }
    }

    return { profile: { ...profile, following } };
  });

  // 팔로우
  fastify.post("/api/profiles/:username/follow", { preHandler: authMiddleware }, async (req, reply) => {
    const username = (req.params as any).username as string;
    const target = await prisma.user.findUnique({
      where: { username },
      select: { id: true },
    });
    if (!target) {
      return reply.code(404).send({ errors: { profile: ["프로필을 찾을 수 없습니다"] } });
    }
    if (target.id === req.userId!) {
      return reply.code(422).send({ errors: { profile: ["자기 자신을 팔로우할 수 없습니다"] } });
    }
    await prisma.follow.upsert({
      where: { followerId_followingId: { followerId: req.userId!, followingId: target.id } },
      create: { followerId: req.userId!, followingId: target.id },
      update: {},
    });
    const profile = await prisma.user.findUnique({
      where: { username },
      select: { id: true, username: true, bio: true, image: true },
    });
    const isFollowing = await prisma.follow.findUnique({
      where: { followerId_followingId: { followerId: req.userId!, followingId: target.id } },
    });
    return { profile: { ...profile, following: !!isFollowing } };
  });

  // 언팔로우
  fastify.delete("/api/profiles/:username/follow", { preHandler: authMiddleware }, async (req, reply) => {
    const username = (req.params as any).username as string;
    const target = await prisma.user.findUnique({
      where: { username },
      select: { id: true },
    });
    if (!target) {
      return reply.code(404).send({ errors: { profile: ["프로필을 찾을 수 없습니다"] } });
    }
    await prisma.follow.deleteMany({
      where: { followerId: req.userId!, followingId: target.id },
    });
    const profile = await prisma.user.findUnique({
      where: { username },
      select: { id: true, username: true, bio: true, image: true },
    });
    const isFollowing = await prisma.follow.findUnique({
      where: { followerId_followingId: { followerId: req.userId!, followingId: target.id } },
    });
    return { profile: { ...profile, following: !!isFollowing } };
  });
});

// ──────────────────────────────────────────────────────────────
// 아티클 API
// ──────────────────────────────────────────────────────────────
await app.register(async function (fastify: FastifyInstance) {
  // 슬러그 생성 헬퍼
  function generateSlug(title: string): string {
    return title.toLowerCase().replace(/\s+/g, "-");
  }

  // 아티클 생성
  fastify.post("/api/articles", { preHandler: authMiddleware }, async (req, reply) => {
    const { title, description, body, tagList = [] } = (req.body as any)?.article || {};
    if (!title || !description || !body) {
      const errs: string[] = [];
      if (!title) errs.push("title은 필수입니다");
      if (!description) errs.push("description은 필수입니다");
      if (!body) errs.push("body는 필수입니다");
      return reply.code(422).send({ errors: { article: errs } });
    }
    const slug = generateSlug(title);
    const article = await prisma.article.create({
      data: {
        slug,
        title,
        description,
        body,
        author: { connect: { id: req.userId! } },
        tags: {
          create: tagList.map((t: string) => ({ tag: t.toLowerCase() })),
        },
      },
      include: {
        author: { select: { username: true, bio: true, image: true } },
        tags: true,
        favorites: true,
      },
    });
    return {
      article: formatArticleResponse(article, false, article.favorites.length),
    };
  });

  // 아티클 목록 조회
  fastify.get("/api/articles", async (req, reply) => {
    const { author, tag, favorited, limit = "20", offset = "0" } = req.query as any;
    const lim = parseInt(limit, 10);
    const off = parseInt(offset, 10);

    const where: any = {};
    if (author) {
      const user = await prisma.user.findUnique({ where: { username: author }, select: { id: true } });
      if (!user) return { articles: [], articlesCount: 0 };
      where.authorId = user.id;
    }
    if (tag) {
      where.tags = { some: { tag: tag.toLowerCase() } };
    }

    // 즐겨찾기 필터링
    if (favorited) {
      const user = await prisma.user.findUnique({
        where: { username: favorited },
        select: { id: true },
      });
      if (!user) return { articles: [], articlesCount: 0 };
      const favorites = await prisma.favorite.findMany({
        where: { userId: user.id },
        select: { articleId: true },
      });
      const articleIds = favorites.map((f) => f.articleId);
      if (articleIds.length === 0) return { articles: [], articlesCount: 0 };
      const articles = await prisma.article.findMany({
        where: { id: { in: articleIds } },
        take: lim,
        skip: off,
        orderBy: { createdAt: "desc" },
        include: { author: { select: { username: true, bio: true, image: true } }, tags: true },
      });
      return {
        articles: articles.map((a) => formatArticleResponse(a, false, a.favorites.length)),
        articlesCount: articles.length,
      };
    }

    const articles = await prisma.article.findMany({
      where,
      take: lim,
      skip: off,
      orderBy: { createdAt: "desc" },
      include: { author: { select: { username: true, bio: true, image: true } }, tags: true, favorites: true },
    });
    const articlesCount = await prisma.article.count({ where });
    return {
      articles: articles.map((a) => formatArticleResponse(a, false, a.favorites.length)),
      articlesCount,
    };
  });

  // 아티클 상세 조회
  fastify.get("/api/articles/:slug", async (req, reply) => {
    const slug = (req.params as any).slug as string;
    const article = await prisma.article.findUnique({
      where: { slug },
      include: { author: { select: { username: true, bio: true, image: true } }, tags: true, favorites: true },
    });
    if (!article) {
      return reply.code(404).send({ errors: { article: ["not found"] } });
    }
    return { article: formatArticleResponse(article, false, article.favorites.length) };
  });

  // 아티클 수정
  fastify.put("/api/articles/:slug", { preHandler: authMiddleware }, async (req, reply) => {
    const slug = (req.params as any).slug as string;
    const article = await prisma.article.findUnique({ where: { slug } });
    if (!article) {
      return reply.code(404).send({ errors: { article: ["not found"] } });
    }
    if (article.authorId !== req.userId!) {
      return reply.code(401).send({ errors: { article: ["이 아티클을 수정할 권한이 없습니다"] } });
    }

    const body = (req.body as any)?.article || {};
    const updates: any = {};
    if (body.title !== undefined) updates.title = body.title;
    if (body.description !== undefined) updates.description = body.description;
    if (body.body !== undefined) updates.body = body.body;

    // 태그 업데이트
    if (body.tagList !== undefined) {
      if (body.tagList === null) {
        return reply.code(422).send({ errors: { article: ["tagList는 null일 수 없습니다"] } });
      }
      if (Array.isArray(body.tagList)) {
        await prisma.articleTag.deleteMany({ where: { articleId: article.id } });
        if (body.tagList.length > 0) {
          await prisma.articleTag.createMany({
            data: body.tagList.map((t: string) => ({ articleId: article.id, tag: t.toLowerCase() })),
          });
        }
      }
    }

    // 슬러그 업데이트
    if (updates.title) {
      updates.slug = generateSlug(updates.title);
    }

    const updated = await prisma.article.update({
      where: { id: article.id },
      data: updates,
      include: { author: { select: { username: true, bio: true, image: true } }, tags: true, favorites: true },
    });
    return { article: formatArticleResponse(updated, false, updated.favorites.length) };
  });

  // 아티클 삭제
  fastify.delete("/api/articles/:slug", { preHandler: authMiddleware }, async (req, reply) => {
    const slug = (req.params as any).slug as string;
    const article = await prisma.article.findUnique({ where: { slug } });
    if (!article) {
      return reply.code(404).send({ errors: { article: ["not found"] } });
    }
    if (article.authorId !== req.userId!) {
      return reply.code(401).send({ errors: { article: ["이 아티클을 삭제할 권한이 없습니다"] } });
    }
    await prisma.article.delete({ where: { id: article.id } });
    return reply.code(204).send();
  });

  // 아티클 피드
  fastify.get("/api/articles/feed", { preHandler: authMiddleware }, async (req, reply) => {
    const { limit = "20", offset = "0" } = req.query as any;
    const lim = parseInt(limit, 10);
    const off = parseInt(offset, 10);

    const follows = await prisma.follow.findMany({
      where: { followerId: req.userId! },
      select: { followingId: true },
    });
    const followingIds = follows.map((f) => f.followingId);

    let articles: any[];
    let articlesCount: number;

    if (followingIds.length === 0) {
      articles = [];
      articlesCount = 0;
    } else {
      articles = await prisma.article.findMany({
        where: { authorId: { in: followingIds } },
        take: lim,
        skip: off,
        orderBy: { createdAt: "desc" },
        include: {
          author: { select: { username: true, bio: true, image: true } },
          tags: true,
          favorites: true,
        },
      });
      articlesCount = await prisma.article.count({
        where: { authorId: { in: followingIds } },
      });
    }

    return {
      articles: articles.map((a) => formatArticleResponse(a, false, a.favorites.length)),
      articlesCount,
    };
  });

  // 코멘트 작성
  fastify.post("/api/articles/:slug/comments", { preHandler: authMiddleware }, async (req, reply) => {
    const slug = (req.params as any).slug as string;
    const article = await prisma.article.findUnique({ where: { slug } });
    if (!article) {
      return reply.code(404).send({ errors: { article: ["not found"] } });
    }
    const { body } = (req.body as any)?.comment || {};
    if (!body) {
      return reply.code(422).send({ errors: { comment: ["body는 필수입니다"] } });
    }
    const comment = await prisma.comment.create({
      data: {
        body,
        articleId: article.id,
        authorId: req.userId!,
      },
      include: { author: { select: { username: true, bio: true, image: true } } },
    });
    return { comment };
  });

  // 코멘트 목록 조회
  fastify.get("/api/articles/:slug/comments", async (req, reply) => {
    const slug = (req.params as any).slug as string;
    const article = await prisma.article.findUnique({ where: { slug } });
    if (!article) {
      return reply.code(404).send({ errors: { article: ["not found"] } });
    }
    const comments = await prisma.comment.findMany({
      where: { articleId: article.id },
      orderBy: { createdAt: "desc" },
      include: { author: { select: { username: true, bio: true, image: true } } },
    });
    return { comments };
  });

  // 코멘트 삭제
  fastify.delete("/api/articles/:slug/comments/:id", { preHandler: authMiddleware }, async (req, reply) => {
    const slug = (req.params as any).slug as string;
    const commentId = parseInt((req.params as any).id as string, 10);
    const comment = await prisma.comment.findUnique({
      where: { id: commentId },
      select: { articleId: true, authorId: true },
    });
    if (!comment) {
      return reply.code(404).send({ errors: { comment: ["not found"] } });
    }
    const article = await prisma.article.findUnique({ where: { id: comment.articleId } });
    if (!article || article.slug !== slug) {
      return reply.code(404).send({ errors: { comment: ["not found"] } });
    }
    if (comment.authorId !== req.userId!) {
      return reply.code(401).send({ errors: { comment: ["이 코멘트를 삭제할 권한이 없습니다"] } });
    }
    await prisma.comment.delete({ where: { id: comment.id } });
    return reply.code(204).send();
  });

  // 즐겨찾기 추가
  fastify.post("/api/articles/:slug/favorite", { preHandler: authMiddleware }, async (req, reply) => {
    const slug = (req.params as any).slug as string;
    const article = await prisma.article.findUnique({
      where: { slug },
      include: { author: { select: { username: true, bio: true, image: true } }, tags: true, favorites: true },
    });
    if (!article) {
      return reply.code(404).send({ errors: { article: ["not found"] } });
    }
    await prisma.favorite.create({
      data: { userId: req.userId!, articleId: article.id },
    });
    return {
      article: formatArticleResponse(article, true, article.favorites.length + 1),
    };
  });

  // 즐겨찾기 삭제
  fastify.delete("/api/articles/:slug/favorite", { preHandler: authMiddleware }, async (req, reply) => {
    const slug = (req.params as any).slug as string;
    const article = await prisma.article.findUnique({
      where: { slug },
      include: { author: { select: { username: true, bio: true, image: true } }, tags: true, favorites: true },
    });
    if (!article) {
      return reply.code(404).send({ errors: { article: ["not found"] } });
    }
    await prisma.favorite.deleteMany({
      where: { userId: req.userId!, articleId: article.id },
    });
    return {
      article: formatArticleResponse(article, false, 0),
    };
  });
});

// ──────────────────────────────────────────────────────────────
// 태그 API
// ──────────────────────────────────────────────────────────────
await app.register(async function (fastify: FastifyInstance) {
  fastify.get("/api/tags", async (req, reply) => {
    const tags = await prisma.articleTag.findMany({
      select: { tag: true },
      distinct: ["tag"],
    });
    return { tags: tags.map((t) => ({ tag: t.tag })) };
  });
});

// ──────────────────────────────────────────────────────────────
// 전역 에러 핸들러
// ──────────────────────────────────────────────────────────────
app.setErrorHandler((error: any, req, reply) => {
  if (error.statusCode === 404) {
    return reply.code(404).send({ errors: { message: ["not found"] } });
  }
  if (error.statusCode === 422) {
    return reply.code(422).send(error.message ? { errors: { _message: [error.message] } } : error);
  }
  if (error.statusCode === 401) {
    return reply.code(401).send(error.message ? { errors: { header: [error.message] } } : { errors: { header: ["인증이 필요합니다"] } });
  }
  req.log.error(error);
  return reply.code(500).send({ errors: { message: ["서버 내부 오류가 발생했습니다"] } });
});

// ──────────────────────────────────────────────────────────────
// 서버 시작
// ──────────────────────────────────────────────────────────────
const start = async () => {
  try {
    const port = Number(process.env.PORT) || 3000;
    await app.listen({ port, host: "0.0.0.0" });
    app.log.info(`서버가 http://0.0.0.0:${port} 에서 실행 중입니다`);
  } catch (err) {
    app.log.error(err);
    process.exit(1);
  }
};

// Graceful shutdown
process.on("SIGINT", async () => {
  await prisma.$disconnect();
  process.exit(0);
});
process.on("SIGTERM", async () => {
  await prisma.$disconnect();
  process.exit(0);
});

start();

