`app.setErrorHandler` 수정:
```javascript
// 기존
app.setErrorHandler((error, request, reply) => {
  if (error.statusCode === 404) {
    return reply.code(404).send({ errors: { message: ["not found"] } });
  }
  if (error.statusCode === 422) {
    return reply.code(422).send(error.message ? { errors: { _message: [error.message] } } : error);
  }
  if (error.statusCode === 401) {
    return reply.code(401).send(error.message ? { errors: { header: [error.message] } } : { errors: { header: ["인증이 필요합니다"] } });
  }
  request.log.error(error);
  return reply.code(500).send({ errors: { message: ["서버 내부 오류가 발생했습니다"] } });
});

// 수정 후
app.setErrorHandler((error, request, reply) => {
  const statusCode = error.statusCode || error.status || 500;
  reply.statusCode = statusCode;

  let body;
  if (statusCode === 404) {
    body = { errors: { message: ["not found"] } };
  } else if (statusCode === 422) {
    body = error.message ? { errors: { _message: [error.message] } } : error;
  } else if (statusCode === 401) {
    body = error.message ? { errors: { header: [error.message] } } : { errors: { header: ["인증이 필요합니다"] } };
  } else if (error.statusCode === 401) {
    body = { errors: { header: ["인증이 필요합니다"] } };
  } else {
    body = { errors: { message: ["서버 내부 오류가 발생했습니다"] } };
  }

  reply.send(body);
});
```

여기서 `error.statusCode === 401`이 두 번 나오는데, 하나는 `statusCode`가 정확히 401인 경우, 다른 하나는 `error.statusCode`가 401인 경우입니다. 조건문을 정리해야 합니다.

수정:
```javascript
app.setErrorHandler((error, request, reply) => {
  const statusCode = error.statusCode || error.status || 500;
  reply.statusCode = statusCode;

  let body;
  if (statusCode === 404) {
    body = { errors: { message: ["not found"] } };
  } else if (statusCode === 422) {
    body = error.message ? { errors: { _message: [error.message] } } : error;
  } else if (statusCode === 401) {
    body = error.message ? { errors: { header: [error.message] } } : { errors: { header: ["인증이 필요합니다"] } };
  } else {
    body = { errors: { message: ["서버 내부 오류가 발생했습니다"] } };
  }

  reply.send(body);
});
```

