npm --version

# v7+이면
npm pkg set type=module

# 또는 직접 수정
cat package.json | sed 's/"type": "commonjs"/"type": "module"/' > temp.json && mv temp.json package.json

# 또는 jq 사용
jq '.type = "module"' package.json > temp.json && mv temp.json package.json
```

