// GET /api/tags
app.get('/api/tags', async (request: any, reply: any) => {
  const tags = await prisma.articleTag.findMany({ select: { tag: true }, distinct: ['tag'] });
  return { tags: tags.map((t) => ({ tag: t.tag })) };
});

// Global error handler
app.setErrorHandler((error: any, request: any, reply: any) => {
  const statusCode = error.statusCode || error.status || 500;
  reply.statusCode = statusCode;
  let body;
  if (statusCode === 404) body = { errors: { message: ['not found'] } };
  else if (statusCode === 422) body = error.message ? { errors: { _message: [error.message] } } : error;
  else if (statusCode === 401) body = error.message ? { errors: { header: [error.message] } } : { errors: { header: ['Authentication token missing'] } };
  else body = { errors: { message: ['Internal server error'] } };
  reply.send(body);
});

// Start server
const start = async () => {
  try {
    const port = Number(process.env.PORT) || 3000;
    await app.listen({ port, host: '0.0.0.0' });
    app.log.info(`Server running at http://0.0.0.0:${port}`);
  } catch (err) {
    app.log.error(err);
    process.exit(1);
  }
};

process.on('SIGINT', async () => { await prisma.$disconnect(); process.exit(0); });
process.on('SIGTERM', async () => { await prisma.$disconnect(); process.exit(0); });

start();
